<?php require __DIR__.'/config.php';require_admin();$m=$_SERVER['REQUEST_METHOD']??'GET';$d=body_json();if($m==='POST'||$m==='PUT'){$name=trim((string)($d['name']??''));$cat=trim((string)($d['category']??''));$desc=trim((string)($d['description']??''));$price=filter_var($d['price']??null,FILTER_VALIDATE_FLOAT);$image=trim((string)($d['image_url']??''));if($name===''||$cat===''||$price===false||$price<=0)json_out(['error'=>'Enter a name, category, and valid price.'],422);if($m==='POST'){$s=$pdo->prepare('INSERT INTO products(name,category,description,price,image_url) VALUES(?,?,?,?,?)');$s->execute([$name,$cat,$desc,$price,$image?:null]);}else{$id=(int)($d['id']??0);if($id<1)json_out(['error'=>'Invalid product.'],422);$s=$pdo->prepare('UPDATE products SET name=?,category=?,description=?,price=?,image_url=? WHERE id=?');$s->execute([$name,$cat,$desc,$price,$image?:null,$id]);}json_out(['ok'=>true]);}if($m==='PATCH'){$id=(int)($d['id']??0);if($id<1)json_out(['error'=>'Invalid product.'],422);$s=$pdo->prepare('UPDATE products SET is_available=? WHERE id=?');$s->execute([!empty($d['is_available'])?1:0,$id]);json_out(['ok'=>true]);}if($m==='DELETE'){$id=(int)($d['id']??0);if($id<1)json_out(['error'=>'Invalid product.'],422);$s=$pdo->prepare('DELETE FROM products WHERE id=?');$s->execute([$id]);json_out(['ok'=>true]);}json_out(['error'=>'Method not allowed.'],405);?>